duckdb.sql("""SELECT COUNT(*) FROM '../data/companies_house.csv' WHERE CompanyStatus = 'Active' AND ((regexp_extract("RegAddress.PostCode", '^[A-Z]+') = 'E') OR (regexp_extract("RegAddress.PostCode", '^[A-Z]+') = 'EC') OR (regexp_extract("RegAddress.PostCode", '^[A-Z]+') = 'N') OR (regexp_extract("RegAddress.PostCode", '^[A-Z]+') = 'NW') OR (regexp_extract("RegAddress.PostCode", '^[A-Z]+') = 'SE') OR (regexp_extract("RegAddress.PostCode", '^[A-Z]+') = 'SW') OR (regexp_extract("RegAddress.PostCode", '^[A-Z]+') = 'W') OR (regexp_extract("RegAddress.PostCode", '^[A-Z]+') = 'WC') ) AND (regexp_extract(CAST("SICCode.SicText_1" AS VARCHAR), '^[0-9]+') LIKE '62%' OR regexp_extract(CAST("SICCode.SicText_2" AS VARCHAR), '^[0-9]+') LIKE '62%' OR regexp_extract(CAST("SICCode.SicText_3" AS VARCHAR), '^[0-9]+') LIKE '62%' OR regexp_extract(CAST("SICCode.SicText_4" AS VARCHAR), '^[0-9]+') LIKE '62%')""").show()
